#include "semantics.h"

#include <stddef.h>  // size_t
#include <stdio.h>   // snprintf

#include "ast.h"
#include "ctx.h"
#include "ir.h"
#include "symtable.h"

// Changes: new, the pass state. Lives on the C stack of semantics_analyze and
// holds no heap memory, so a THROW leaks nothing (scopes are owned by AST
// nodes).
typedef struct {
  // The PROGRAM node being analysed
  AstNode* program;
  // Current scope, where a new declaration goes
  Symtable* scope;
  // The DEF whose body is being checked, NULL outside phase 2
  AstNode* def;
  // Next free slot (ir_index) of a variable of def
  size_t next_slot;
} Sema;

// Changes: new, the number of parameters of a DEF; stores its PARAM_LIST in
// *params (NULL when the DEF omits it).
static size_t def_param_list(Ctx* ctx, AstNode* def, AstNode** params) {
  *params = NULL;
  if (ast_node_get_child_count(def) <= AST_DEF_PARAM_LIST)
    return 0;
  *params = ast_node_child(ctx, def, AST_DEF_PARAM_LIST);
  return ast_node_get_child_count(*params);
}

// Changes: new, the one table of the five value types: data type, IR type and
// the spelling used in messages and member keys (ADR-0002).
typedef struct {
  AstDataType data_type;
  IrType ir_type;
  const char* name;
} TypeRow;

static const TypeRow TYPES[] = {
    {AST_DATA_TYPE_INT, IR_INT, "Int"},
    {AST_DATA_TYPE_DOUBLE, IR_DOUBLE, "Double"},
    {AST_DATA_TYPE_BOOLEAN, IR_BOOL, "Boolean"},
    {AST_DATA_TYPE_STRING, IR_STRING, "String"},
    {AST_DATA_TYPE_UNIT, IR_UNIT, "Unit"},
};
#define TYPE_COUNT (sizeof(TYPES) / sizeof(TYPES[0]))

// Changes: new, data type to the IR type stored in symbols (type table).
static IrType data_type_to_ir(Ctx* ctx, AstDataType type) {
  for (size_t i = 0; i < TYPE_COUNT; i++)
    if (TYPES[i].data_type == type)
      return TYPES[i].ir_type;
  THROW(E_INTERNAL_ERROR, "semantic analysis met an expression without a type");
  return IR_UNIT;
}

// Changes: new, the data type of a type annotation node; one without a type is
// an internal error.
// Also: positions print as size_t (%zu).
static AstDataType annotation_type(Ctx* ctx, const AstNode* annotation) {
  if (ast_node_get_type(annotation) != AST_NODE_TYPE_ANNOTATION)
    THROW(E_INTERNAL_ERROR, "expected a type annotation at %zu:%zu",
          ast_node_get_line(annotation), ast_node_get_column(annotation));
  AstDataType type = ast_node_get_data_type(annotation);
  if (type == AST_DATA_TYPE_UNKNOWN)
    THROW(E_INTERNAL_ERROR,
          "semantic analysis met an expression without a type");
  return type;
}

// Changes: new, the IR type of a type annotation node.
static IrType annotation_to_ir(Ctx* ctx, AstNode* annotation) {
  return data_type_to_ir(ctx, annotation_type(ctx, annotation));
}

// Changes: new, the IR type of the parameter at index of a PARAM_LIST.
static IrType param_type(Ctx* ctx, AstNode* params, size_t index) {
  AstNode* param = ast_node_child(ctx, params, index);
  AstNode* type = ast_node_child(ctx, param, AST_PARAM_TYPE);
  return annotation_to_ir(ctx, type);
}

// Changes: new, IR type of a symbol to the data type of an expression (type
// table).
static AstDataType ir_to_data_type(Ctx* ctx, IrType type) {
  for (size_t i = 0; i < TYPE_COUNT; i++)
    if (TYPES[i].ir_type == type)
      return TYPES[i].data_type;
  THROW(E_INTERNAL_ERROR, "semantic analysis met an unknown IR type");
  return AST_DATA_TYPE_UNKNOWN;
}

// Changes: new, the spelling of a data type in error messages (type table).
static const char* data_type_name(AstDataType type) {
  for (size_t i = 0; i < TYPE_COUNT; i++)
    if (TYPES[i].data_type == type)
      return TYPES[i].name;
  return "an unknown type";
}

// Changes: new, the type of an already checked expression; an untyped one is an
// internal error.
// Also: positions print as size_t (%zu).
static AstDataType expr_type(Ctx* ctx, const AstNode* node) {
  AstDataType type = ast_node_get_data_type(node);
  if (type == AST_DATA_TYPE_UNKNOWN)
    THROW(E_INTERNAL_ERROR,
          "semantic analysis met an untyped expression at %zu:%zu",
          ast_node_get_line(node), ast_node_get_column(node));
  return type;
}

// Changes: new, whether from may be used where to is required: same type, or
// Int for Double.
static bool is_compatible(AstDataType from, AstDataType to) {
  return from == to ||
         (from == AST_DATA_TYPE_INT && to == AST_DATA_TYPE_DOUBLE);
}

// Changes: new, whether a type is Int or Double.
static bool is_number(AstDataType type) {
  return type == AST_DATA_TYPE_INT || type == AST_DATA_TYPE_DOUBLE;
}

// Changes: new, wraps the Int expression in an INT_TO_DOUBLE in its parent's
// slot (ast_node_wrap). The node stays valid, its slot now holds the wrapper.
// Also: positions print as size_t (%zu).
static void widen_node(Ctx* ctx, AstNode* node) {
  if (ast_node_get_data_type(node) != AST_DATA_TYPE_INT)
    THROW(E_INTERNAL_ERROR, "only an Int can be widened, at %zu:%zu",
          ast_node_get_line(node), ast_node_get_column(node));
  AstNode* wrapper = ast_node_wrap(ctx, node, AST_NODE_INT_TO_DOUBLE);
  ast_node_set_data_type(wrapper, AST_DATA_TYPE_DOUBLE);
}

// Changes: new, the checked expression must fit target: same type passes, Int
// is widened to Double in place, anything else stops with code (6 values, 5
// arguments); what names the construct in the message.
// Also: positions print as size_t (%zu).
static void require_compatible(Ctx* ctx,
                               AstNode* node,
                               AstDataType target,
                               ExitCode code,
                               const char* what) {
  AstDataType actual = expr_type(ctx, node);
  if (!is_compatible(actual, target))
    THROW(code, "%s at %zu:%zu needs %s but the value is %s", what,
          ast_node_get_line(node), ast_node_get_column(node),
          data_type_name(target), data_type_name(actual));
  if (actual == AST_DATA_TYPE_INT && target == AST_DATA_TYPE_DOUBLE)
    widen_node(ctx, node);
}

// Changes: new, the expression must be a Boolean (exit 6), nothing is widened.
// Also: positions print as size_t (%zu).
static void require_boolean(Ctx* ctx, AstNode* node, const char* what) {
  AstDataType actual = expr_type(ctx, node);
  if (actual != AST_DATA_TYPE_BOOLEAN)
    THROW(E_SEMANTIC_TYPE_ERROR, "%s at %zu:%zu must be Boolean but is %s", what,
          ast_node_get_line(node), ast_node_get_column(node),
          data_type_name(actual));
}

// Changes: new, the data of a function symbol. The parameter array (NULL for
// none) is owned by the symtable once inserted; nothing may THROW between
// filling and inserting it.
static SymtableData function_data(Ctx* ctx,
                                  IrType return_type,
                                  size_t ir_index,
                                  size_t param_count) {
  SymtableData data = {
      .symbol_type = SYMBOL_FUNCTION,
      .ir_type = return_type,
      .ir_index = ir_index,
      .param_count = param_count,
      .param_types = NULL,
      .is_val = false,
  };
  if (param_count > 0)
    data.param_types = TRY_MALLOC(sizeof(IrType) * param_count);
  return data;
}

// Changes: new, phase 0: the eight member entries "<ReceiverType>.<member>"
// (ADR-0002), the receiver is the only parameter.
static void insert_members(Ctx* ctx, Sema* sema) {
  static const struct {
    const char* key;
    IrType receiver;
    IrType result;
    IrFunctionType function;
  } members[] = {
      {"Int.toString", IR_INT, IR_STRING, IR_FX_TO_STR},
      {"Double.toString", IR_DOUBLE, IR_STRING, IR_FX_TO_STR},
      {"Boolean.toString", IR_BOOL, IR_STRING, IR_FX_TO_STR},
      {"String.toString", IR_STRING, IR_STRING, IR_FX_TO_STR},
      {"Unit.toString", IR_UNIT, IR_STRING, IR_FX_TO_STR},
      {"Double.toInt", IR_DOUBLE, IR_INT, IR_FX_TO_INT},
      // The IR has a floor instruction instead of a function, ir_index is
      // unused and IR generation recognises the member by its name
      {"Double.floor", IR_DOUBLE, IR_DOUBLE, IR_FX_USER},
      {"String.length", IR_STRING, IR_INT, IR_FX_STR_LEN},
  };
  for (size_t i = 0; i < sizeof(members) / sizeof(members[0]); i++) {
    SymtableData data = function_data(ctx, members[i].result,
                                      (size_t)members[i].function, 1);
    data.param_types[0] = members[i].receiver;
    symtable_insert(ctx, sema->scope, (char*)members[i].key, data);
  }
}

// Changes: new, declares one DEF as a global function symbol. A name already
// global is exit 4, an omitted return type is a Unit placeholder until
// inferred, a @main with a parameter is exit 5.
// Also: positions print as size_t (%zu).
static void collect_function(Ctx* ctx, Sema* sema, AstNode* def, size_t id) {
  AstNode* ident = ast_node_child(ctx, def, AST_DEF_IDENT);
  const char* name = ast_node_get_name(ident);

  if (symtable_lookup(sema->scope, (char*)name, false) != NULL)
    THROW(E_SEMANTIC_REDEFINITION_ERROR,
          "redefinition of function '%s' at %zu:%zu", name,
          ast_node_get_line(ident), ast_node_get_column(ident));

  AstNode* rettype = ast_node_child(ctx, def, AST_DEF_RETTYPE);
  IrType return_type = IR_UNIT;
  if (ast_node_get_type(rettype) != AST_NODE_NONE)
    return_type = annotation_to_ir(ctx, rettype);

  AstNode* params = NULL;
  size_t param_count = def_param_list(ctx, def, &params);

  if ((ast_node_get_flags(def) & (unsigned)AST_FLAG_MAIN) && param_count > 0)
    THROW(E_SEMANTIC_ARGUMENT_ERROR,
          "@main function '%s' at %zu:%zu must not have parameters", name,
          ast_node_get_line(ident), ast_node_get_column(ident));

  // Check every parameter type before allocating the array, so a THROW here
  // has nothing to free
  for (size_t i = 0; i < param_count; i++)
    (void)param_type(ctx, params, i);
  SymtableData data = function_data(ctx, return_type, id, param_count);
  for (size_t i = 0; i < param_count; i++)
    data.param_types[i] = param_type(ctx, params, i);

  symtable_insert(ctx, sema->scope, (char*)name, data);
  ast_node_set_symbol(ident, symtable_lookup(sema->scope, (char*)name, false));
}

// Changes: new, declares one DEF as a global function symbol. A name already
// global is exit 4, an omitted return type is a Unit placeholder until
// inferred, a @main with a parameter is exit 5.
// Also: positions print as size_t (%zu).
static void collect_functions(Ctx* ctx, Sema* sema) {
  size_t mains = 0;
  size_t count = ast_node_get_child_count(sema->program);
  for (size_t id = 0; id < count; id++) {
    AstNode* def = ast_node_child(ctx, sema->program, id);
    if (ast_node_get_type(def) != AST_NODE_DEF)
      THROW(E_INTERNAL_ERROR, "unexpected top-level node at %zu:%zu",
            ast_node_get_line(def), ast_node_get_column(def));

    if (ast_node_get_flags(def) & (unsigned)AST_FLAG_MAIN) {
      mains++;
      if (mains > 1) {
        AstNode* ident = ast_node_child(ctx, def, AST_DEF_IDENT);
        THROW(E_SEMANTIC_REDEFINITION_ERROR,
              "more than one @main function, second one '%s' at %zu:%zu",
              ast_node_get_name(ident), ast_node_get_line(ident),
              ast_node_get_column(ident));
      }
    }

    collect_function(ctx, sema, def, id);
  }
  if (mains == 0)
    THROW(E_SEMANTIC_UNDEFINED_ERROR, "no @main function in the program");
}

// Changes: new, declares a parameter, val, var or for variable in the current
// scope. A name already in that scope is exit 4, checked before the insert so
// no symbol an AST node points at is replaced.
// Also: positions print as size_t (%zu).
static void declare_variable(Ctx* ctx,
                             Sema* sema,
                             AstNode* ident,
                             IrType type,
                             bool is_val,
                             size_t slot) {
  const char* name = ast_node_get_name(ident);
  if (symtable_lookup(sema->scope, (char*)name, false) != NULL)
    THROW(E_SEMANTIC_REDEFINITION_ERROR, "redefinition of '%s' at %zu:%zu", name,
          ast_node_get_line(ident), ast_node_get_column(ident));

  SymtableData data = {
      .symbol_type = SYMBOL_VARIABLE,
      .ir_type = type,
      .ir_index = slot,
      .param_count = 0,
      .param_types = NULL,
      .is_val = is_val,
  };
  symtable_insert(ctx, sema->scope, (char*)name, data);
  ast_node_set_symbol(ident, symtable_lookup(sema->scope, (char*)name, false));
}

// Changes: new, resolves an identifier to a visible variable, from the current
// scope outward; none is exit 3.
// Also: positions print as size_t (%zu).
static SymtableData* resolve_variable(Ctx* ctx, Sema* sema, AstNode* ident) {
  const char* name = ast_node_get_name(ident);
  SymtableData* symbol = symtable_lookup(sema->scope, (char*)name, true);
  if (symbol == NULL || symbol->symbol_type != SYMBOL_VARIABLE)
    THROW(E_SEMANTIC_UNDEFINED_ERROR, "undefined variable '%s' at %zu:%zu", name,
          ast_node_get_line(ident), ast_node_get_column(ident));
  ast_node_set_symbol(ident, symbol);
  return symbol;
}

// Changes: new, resolves a callee among the global functions only, so a
// variable never hides a function; none is exit 3.
// Also: positions print as size_t (%zu).
static SymtableData* resolve_function(Ctx* ctx, AstNode* ident) {
  const char* name = ast_node_get_name(ident);
  SymtableData* symbol =
      symtable_lookup(&ctx->global_symtable, (char*)name, false);
  if (symbol == NULL || symbol->symbol_type != SYMBOL_FUNCTION)
    THROW(E_SEMANTIC_UNDEFINED_ERROR, "undefined function '%s' at %zu:%zu", name,
          ast_node_get_line(ident), ast_node_get_column(ident));
  ast_node_set_symbol(ident, symbol);
  return symbol;
}

// Changes: new, the DEF of a user function symbol, NULL for a built-in or
// member (the built-in test).
static AstNode* def_of_symbol(Ctx* ctx,
                              const Sema* sema,
                              const SymtableData* symbol) {
  if (symbol->ir_index >= ast_node_get_child_count(sema->program))
    return NULL;
  AstNode* def = ast_node_child(ctx, sema->program, symbol->ir_index);
  AstNode* ident = ast_node_child(ctx, def, AST_DEF_IDENT);
  return ast_node_get_symbol(ident) == symbol ? def : NULL;
}

static void check_stmt(Ctx* ctx, Sema* sema, AstNode* node);
static void check_expr(Ctx* ctx, Sema* sema, AstNode* node);
static void check_def(Ctx* ctx, Sema* sema, AstNode* def);

// Changes: new, checks every child of node from index first as an expression.
static void check_expr_children(Ctx* ctx,
                                Sema* sema,
                                AstNode* node,
                                size_t first) {
  size_t count = ast_node_get_child_count(node);
  for (size_t i = first; i < count; i++) {
    AstNode* child = ast_node_child(ctx, node, i);
    check_expr(ctx, sema, child);
  }
}

// Changes: new, a VAL or VAR. The initializer is checked before the declaration
// (it still sees a shadowed outer name); it gives the type, or must fit the
// annotation (exit 6).
static void check_val_var(Ctx* ctx, Sema* sema, AstNode* node) {
  AstNode* ident = ast_node_child(ctx, node, AST_VAL_IDENT);
  AstNode* annotation = ast_node_child(ctx, node, AST_VAL_TYPE);
  AstNode* init = ast_node_child(ctx, node, AST_VAL_INIT);

  check_expr(ctx, sema, init);

  IrType type = IR_UNIT;
  if (ast_node_get_type(annotation) != AST_NODE_NONE) {
    type = annotation_to_ir(ctx, annotation);
    require_compatible(ctx, init, ir_to_data_type(ctx, type),
                       E_SEMANTIC_TYPE_ERROR, "initializer");
  } else {
    type = data_type_to_ir(ctx, expr_type(ctx, init));
  }
  declare_variable(ctx, sema, ident, type,
                   ast_node_get_type(node) == AST_NODE_VAL, sema->next_slot++);
}

// Changes: new, the ASSIGN target must be a visible writable variable: a val,
// parameter or for variable, and any name that is no visible variable, is exit
// 7 (PDF 2.2).
// Also: positions print as size_t (%zu).
static void check_assign_target(Ctx* ctx, Sema* sema, AstNode* target) {
  const char* name = ast_node_get_name(target);
  SymtableData* symbol = symtable_lookup(sema->scope, (char*)name, true);
  if (symbol == NULL || symbol->symbol_type != SYMBOL_VARIABLE)
    THROW(E_SEMANTIC_REWRITE_ERROR,
          "assignment to '%s' at %zu:%zu, which is no defined variable", name,
          ast_node_get_line(target), ast_node_get_column(target));
  ast_node_set_symbol(target, symbol);
  if (symbol->is_val)
    THROW(E_SEMANTIC_REWRITE_ERROR,
          "assignment to the read-only variable '%s' at %zu:%zu",
          ast_node_get_name(target), ast_node_get_line(target),
          ast_node_get_column(target));
}

// Changes: new, an ASSIGN: writable target, then a value compatible with its
// type (exit 6).
static void check_assign(Ctx* ctx, Sema* sema, AstNode* node) {
  AstNode* target = ast_node_child(ctx, node, AST_ASSIGN_IDENT);
  AstNode* value = ast_node_child(ctx, node, AST_ASSIGN_VALUE);
  check_assign_target(ctx, sema, target);
  const SymtableData* symbol = ast_node_get_symbol(target);
  check_expr(ctx, sema, value);
  require_compatible(ctx, value, ir_to_data_type(ctx, symbol->ir_type),
                     E_SEMANTIC_TYPE_ERROR, "assigned value");
}

// Changes: new, one mechanism for every position whose value matters (replaces
// Tail and the tail variants).
// A ResultRule says how a position treats the value of the last statement of a
// block, and of each branch of an `if` ending it:
//  - declared: the position states its type (a function body with a declared
//    return type). Every path must end in a return or a compatible value (Int
//    widened to Double); a declared Unit discards every value.
//  - not declared: the type is whatever the value has (omitted return type, if
//    expression); the branches of an `if` need one common type, Int and Double
//    give Double.
//  - else_required: a missing else is exit 6 (an if expression). Without it a
//    missing else counts as a `()` branch.
// A branch ending in `return` yields no value (AST_DATA_TYPE_UNKNOWN) and takes
// the other branch's type. A NULL rule means the value is discarded.
typedef struct {
  bool declared;
  AstDataType type;
  bool else_required;
} ResultRule;

// The rule of an if expression: no declared type, a missing else is exit 6
static const ResultRule IF_EXPRESSION_RULE = {
    .declared = false,
    .type = AST_DATA_TYPE_UNKNOWN,
    .else_required = true,
};

// Changes: new, the body result rule of a DEF, the one place that knows whether
// a function declares its return type.
static ResultRule body_rule(Ctx* ctx, AstNode* def) {
  AstNode* rettype = ast_node_child(ctx, def, AST_DEF_RETTYPE);
  ResultRule rule = {
      .declared = false, .type = AST_DATA_TYPE_UNIT, .else_required = false};
  if (ast_node_get_type(rettype) != AST_NODE_NONE) {
    rule.declared = true;
    rule.type = annotation_type(ctx, rettype);
  }
  return rule;
}

// Changes: new, a RETURN. Its value is checked first (exit 3 wins); without a
// declared return type any return is exit 6, a declared Unit discards the
// value, any other type needs a compatible value.
// Also: positions print as size_t (%zu).
static void check_return(Ctx* ctx, Sema* sema, AstNode* node) {
  AstNode* value = ast_node_child(ctx, node, AST_RETURN_VALUE);
  bool has_value = ast_node_get_type(value) != AST_NODE_NONE;
  if (has_value)
    check_expr(ctx, sema, value);

  ResultRule rule = body_rule(ctx, sema->def);
  if (!rule.declared)
    THROW(E_SEMANTIC_TYPE_ERROR,
          "return at %zu:%zu in a function without a declared return type",
          ast_node_get_line(node), ast_node_get_column(node));
  if (rule.type == AST_DATA_TYPE_UNIT)
    return;
  if (!has_value)
    THROW(E_SEMANTIC_TYPE_ERROR,
          "bare return at %zu:%zu in a function returning %s",
          ast_node_get_line(node), ast_node_get_column(node),
          data_type_name(rule.type));
  require_compatible(ctx, value, rule.type, E_SEMANTIC_TYPE_ERROR,
                     "returned value");
}

// Changes: new, whether the rule asks for a value of a declared non-Unit type.
static bool must_yield_value(const ResultRule* rule) {
  return rule->declared && rule->type != AST_DATA_TYPE_UNIT;
}

// Changes: new, whether a missing else is exit 6 under the rule.
static bool needs_else(const ResultRule* rule) {
  return rule->declared ? must_yield_value(rule) : rule->else_required;
}

// Changes: new, whether a statement kind yields Unit at the end of a block (a
// return yields no value).
static bool is_unit_statement(AstNodeType type) {
  return type == AST_NODE_VAL || type == AST_NODE_VAR ||
         type == AST_NODE_ASSIGN || type == AST_NODE_WHILE ||
         type == AST_NODE_FOR;
}

// Changes: new, widens what a branch of an if expression yields: the last
// statement of a BLOCK, both branches of an else-if IF, or an Int expression
// (wrapped in place). A branch without a value is left alone.
// NOLINTNEXTLINE(misc-no-recursion)
static void widen_branch(Ctx* ctx, AstNode* node) {
  switch (ast_node_get_type(node)) {
    case AST_NODE_BLOCK:
      if (ast_node_get_child_count(node) > 0)
        widen_branch(
            ctx, ast_node_child(ctx, node, ast_node_get_child_count(node) - 1));
      break;
    case AST_NODE_IF:
      widen_branch(ctx, ast_node_child(ctx, node, AST_IF_THEN));
      widen_branch(ctx, ast_node_child(ctx, node, AST_IF_ELSE));
      ast_node_set_data_type(node, AST_DATA_TYPE_DOUBLE);
      break;
    case AST_NODE_NONE:
    case AST_NODE_RETURN:
      break;
    default:
      widen_node(ctx, node);
      break;
  }
}

// Changes: new, the common type of the two branches of an `if` under a rule. No
// value on both sides is UNKNOWN, a declared type wins, a valueless branch
// takes the other's type, Int with Double gives Double; anything else is exit
// 6.
// Also: positions print as size_t (%zu).
static AstDataType unify_branches(Ctx* ctx,
                                  AstNode* node,
                                  const ResultRule* rule,
                                  AstDataType then_type,
                                  AstDataType else_type) {
  if (then_type == AST_DATA_TYPE_UNKNOWN && else_type == AST_DATA_TYPE_UNKNOWN)
    return AST_DATA_TYPE_UNKNOWN;
  if (rule->declared)
    return rule->type;
  if (then_type == AST_DATA_TYPE_UNKNOWN)
    return else_type;
  if (else_type == AST_DATA_TYPE_UNKNOWN || then_type == else_type)
    return then_type;
  if (!is_number(then_type) || !is_number(else_type))
    THROW(E_SEMANTIC_TYPE_ERROR,
          "branches of the if at %zu:%zu have different types %s and %s",
          ast_node_get_line(node), ast_node_get_column(node),
          data_type_name(then_type), data_type_name(else_type));
  size_t int_side = then_type == AST_DATA_TYPE_INT ? AST_IF_THEN : AST_IF_ELSE;
  widen_branch(ctx, ast_node_child(ctx, node, int_side));
  return AST_DATA_TYPE_DOUBLE;
}

static AstDataType check_result_stmt(Ctx* ctx,
                                     Sema* sema,
                                     AstNode* stmt,
                                     const ResultRule* rule);
static AstDataType check_block(Ctx* ctx,
                               Sema* sema,
                               AstNode* block,
                               const ResultRule* rule);

// Changes: new, checks a branch of an IF under the rule and returns what it
// yields (NULL rule: a statement, Unit).
static AstDataType check_branch(Ctx* ctx,
                                Sema* sema,
                                AstNode* branch,
                                const ResultRule* rule) {
  if (rule != NULL)
    return check_result_stmt(ctx, sema, branch, rule);
  check_stmt(ctx, sema, branch);
  return AST_DATA_TYPE_UNIT;
}

// Changes: new, checks an IF under the rule (NULL: a statement, the IF is
// Unit). Boolean condition in the enclosing scope, the branches (else if by
// recursion), the missing else rule and unify_branches. Returns UNKNOWN when
// every branch returns.
// NOLINTNEXTLINE(misc-no-recursion)
// Also: positions print as size_t (%zu).
static AstDataType check_if_node(Ctx* ctx,
                                 Sema* sema,
                                 AstNode* node,
                                 const ResultRule* rule) {
  AstNode* cond = ast_node_child(ctx, node, AST_IF_COND);
  AstNode* else_branch = ast_node_child(ctx, node, AST_IF_ELSE);
  check_expr(ctx, sema, cond);
  require_boolean(ctx, cond, "condition of if");

  AstNode* then_branch = ast_node_child(ctx, node, AST_IF_THEN);
  AstDataType then_type = check_branch(ctx, sema, then_branch, rule);
  AstDataType else_type = AST_DATA_TYPE_UNIT;
  switch (ast_node_get_type(else_branch)) {
    case AST_NODE_NONE:
      if (rule != NULL && needs_else(rule))
        THROW(E_SEMANTIC_TYPE_ERROR, "if at %zu:%zu has no else but needs a %s",
              ast_node_get_line(node), ast_node_get_column(node),
              rule->declared ? data_type_name(rule->type) : "value");
      break;
    case AST_NODE_IF:
      else_type = check_if_node(ctx, sema, else_branch, rule);
      break;
    default:
      else_type = check_branch(ctx, sema, else_branch, rule);
      break;
  }

  AstDataType result = AST_DATA_TYPE_UNIT;
  if (rule != NULL)
    result = unify_branches(ctx, node, rule, then_type, else_type);
  ast_node_set_data_type(
      node, result == AST_DATA_TYPE_UNKNOWN ? AST_DATA_TYPE_UNIT : result);
  return result;
}

// Changes: new, an IF reached as a statement or expression: EXPR-flagged ones
// use IF_EXPRESSION_RULE, others are statements.
static void check_if(Ctx* ctx, Sema* sema, AstNode* node) {
  bool as_expr = (ast_node_get_flags(node) & (unsigned)AST_FLAG_EXPR) != 0;
  (void)check_if_node(ctx, sema, node, as_expr ? &IF_EXPRESSION_RULE : NULL);
}

// Changes: new, checks the last statement under the rule and returns what it
// yields: BLOCK/IF by recursion (an EXPR-flagged IF is an if expression
// wherever it stands), return UNKNOWN, val/var/assign/while/for Unit, an
// expression its type, widened in place to a declared type.
// NOLINTNEXTLINE(misc-no-recursion)
// Also: positions print as size_t (%zu).
static AstDataType check_result_stmt(Ctx* ctx,
                                     Sema* sema,
                                     AstNode* stmt,
                                     const ResultRule* rule) {
  AstNodeType kind = ast_node_get_type(stmt);
  if (kind == AST_NODE_BLOCK)
    return check_block(ctx, sema, stmt, rule);
  if (kind == AST_NODE_IF) {
    if (ast_node_get_flags(stmt) & (unsigned)AST_FLAG_EXPR) {
      AstDataType type = check_if_node(ctx, sema, stmt, &IF_EXPRESSION_RULE);
      if (type == AST_DATA_TYPE_UNKNOWN || !rule->declared)
        return type;
      if (must_yield_value(rule))
        require_compatible(ctx, stmt, rule->type, E_SEMANTIC_TYPE_ERROR,
                           "result of the function");
      return rule->type;
    }
    ResultRule nested = *rule;
    nested.else_required = false;
    return check_if_node(ctx, sema, stmt, &nested);
  }
  if (kind == AST_NODE_RETURN) {
    check_stmt(ctx, sema, stmt);
    return AST_DATA_TYPE_UNKNOWN;
  }
  if (is_unit_statement(kind)) {
    check_stmt(ctx, sema, stmt);
    if (must_yield_value(rule))
      THROW(E_SEMANTIC_TYPE_ERROR,
            "statement at %zu:%zu ends a function that must return %s",
            ast_node_get_line(stmt), ast_node_get_column(stmt),
            data_type_name(rule->type));
    return AST_DATA_TYPE_UNIT;
  }
  check_expr(ctx, sema, stmt);
  if (!rule->declared)
    return expr_type(ctx, stmt);
  if (must_yield_value(rule))
    require_compatible(ctx, stmt, rule->type, E_SEMANTIC_TYPE_ERROR,
                       "result of the function");
  return rule->type;
}

// Changes: new, a BLOCK in its own nested scope (kept by the BLOCK). With a
// rule its last statement goes through check_result_stmt and the block yields
// its type; an empty block yields Unit.
// NOLINTNEXTLINE(misc-no-recursion)
// Also: positions print as size_t (%zu).
static AstDataType check_block(Ctx* ctx,
                               Sema* sema,
                               AstNode* block,
                               const ResultRule* rule) {
  Symtable* outer = sema->scope;
  sema->scope = ast_node_attach_scope(ctx, block, outer);
  size_t count = ast_node_get_child_count(block);
  if (rule != NULL && count == 0 && must_yield_value(rule))
    THROW(E_SEMANTIC_TYPE_ERROR,
          "empty block at %zu:%zu in a function that must return %s",
          ast_node_get_line(block), ast_node_get_column(block),
          data_type_name(rule->type));
  AstDataType result = AST_DATA_TYPE_UNIT;
  for (size_t i = 0; i < count; i++) {
    if (rule != NULL && i + 1 == count) {
      AstNode* last = ast_node_child(ctx, block, i);
      result = check_result_stmt(ctx, sema, last, rule);
    } else {
      AstNode* stmt = ast_node_child(ctx, block, i);
      check_stmt(ctx, sema, stmt);
    }
  }
  sema->scope = outer;
  return result;
}

// Changes: new, a WHILE: Boolean condition in the enclosing scope, body in its
// own scope.
static void check_while(Ctx* ctx, Sema* sema, AstNode* node) {
  AstNode* cond = ast_node_child(ctx, node, AST_WHILE_COND);
  AstNode* body = ast_node_child(ctx, node, AST_WHILE_BODY);
  check_expr(ctx, sema, cond);
  require_boolean(ctx, cond, "condition of while");
  check_stmt(ctx, sema, body);
}

// Changes: new, whether node is the literal Int 0 or -0, the only steps
// rejected at compile time.
static bool is_zero_literal(Ctx* ctx, AstNode* node) {
  if (ast_node_get_type(node) == AST_NODE_NEG &&
      ast_node_get_child_count(node) == 1) {
    AstNode* operand = ast_node_child(ctx, node, AST_UNARY_OPERAND);
    node = operand;
  }
  return ast_node_get_type(node) == AST_NODE_INT_LIT &&
         ast_node_get_value(node).int_value == 0;
}

// Changes: new, a RANGE_TO or RANGE_UNTIL: Int bounds and step (exit 6); a
// literal 0 or -0 step is exit 10.
// Also: positions print as size_t (%zu).
static void check_range(Ctx* ctx, Sema* sema, AstNode* node) {
  size_t count = ast_node_get_child_count(node);
  for (size_t i = 0; i < count; i++) {
    AstNode* child = ast_node_child(ctx, node, i);
    if (ast_node_get_type(child) == AST_NODE_NONE)
      continue;
    check_expr(ctx, sema, child);
    AstDataType actual = expr_type(ctx, child);
    if (actual != AST_DATA_TYPE_INT)
      THROW(E_SEMANTIC_TYPE_ERROR,
            "%s of a range at %zu:%zu must be Int but is %s",
            i == AST_RANGE_STEP ? "step" : "bound", ast_node_get_line(child),
            ast_node_get_column(child), data_type_name(actual));
    if (i == AST_RANGE_STEP && is_zero_literal(ctx, child))
      THROW(E_SEMANTIC_OTHER_ERROR, "step of a range at %zu:%zu is zero",
            ast_node_get_line(child), ast_node_get_column(child));
  }
}

// Changes: new, a FOR: source in the enclosing scope, then a loop-variable
// scope (owned by the FOR) with the read-only Int loop variable, Boolean guards
// in it, the body scope nested inside.
static void check_for(Ctx* ctx, Sema* sema, AstNode* node) {
  AstNode* ident = ast_node_child(ctx, node, AST_FOR_IDENT);
  AstNode* source = ast_node_child(ctx, node, AST_FOR_SOURCE);
  AstNode* body = ast_node_child(ctx, node, AST_FOR_BODY);

  check_expr(ctx, sema, source);

  Symtable* outer = sema->scope;
  sema->scope = ast_node_attach_scope(ctx, node, outer);
  declare_variable(ctx, sema, ident, IR_INT, true, sema->next_slot++);
  ast_node_set_data_type(ident, AST_DATA_TYPE_INT);
  size_t count = ast_node_get_child_count(node);
  for (size_t i = AST_FOR_FIRST_GUARD; i < count; i++) {
    AstNode* guard = ast_node_child(ctx, node, i);
    check_expr(ctx, sema, guard);
    require_boolean(ctx, guard, "guard of for");
  }
  check_stmt(ctx, sema, body);
  sema->scope = outer;
}

// Changes: new, an IDENT used as a value takes the type of its variable symbol.
static void check_ident(Ctx* ctx, Sema* sema, AstNode* node) {
  const SymtableData* symbol = resolve_variable(ctx, sema, node);
  ast_node_set_data_type(node, ir_to_data_type(ctx, symbol->ir_type));
}

// Changes: new, a literal has the type of its kind.
// Also: positions print as size_t (%zu).
static void check_literal(Ctx* ctx, Sema* sema, AstNode* node) {
  (void)sema;
  switch (ast_node_get_type(node)) {
    case AST_NODE_INT_LIT:
      ast_node_set_data_type(node, AST_DATA_TYPE_INT);
      break;
    case AST_NODE_DOUBLE_LIT:
      ast_node_set_data_type(node, AST_DATA_TYPE_DOUBLE);
      break;
    case AST_NODE_STRING_LIT:
      ast_node_set_data_type(node, AST_DATA_TYPE_STRING);
      break;
    case AST_NODE_BOOL_LIT:
      ast_node_set_data_type(node, AST_DATA_TYPE_BOOLEAN);
      break;
    case AST_NODE_UNIT_LIT:
      ast_node_set_data_type(node, AST_DATA_TYPE_UNIT);
      break;
    default:
      THROW(E_INTERNAL_ERROR, "expected a literal at %zu:%zu",
            ast_node_get_line(node), ast_node_get_column(node));
  }
}

// Changes: new, the spelling of an operator node in error messages.
static const char* operator_name(AstNodeType type) {
  switch (type) {
    case AST_NODE_ADD:
      return "+";
    case AST_NODE_SUB:
      return "-";
    case AST_NODE_MUL:
      return "*";
    case AST_NODE_DIV:
      return "/";
    case AST_NODE_EQ:
      return "==";
    case AST_NODE_NEQ:
      return "!=";
    case AST_NODE_LT:
      return "<";
    case AST_NODE_GT:
      return ">";
    case AST_NODE_LE:
      return "<=";
    case AST_NODE_GE:
      return ">=";
    case AST_NODE_AND:
      return "&&";
    case AST_NODE_OR:
      return "||";
    case AST_NODE_NOT:
      return "!";
    case AST_NODE_NEG:
      return "-";
    default:
      return "operator";
  }
}

// Changes: new, exit 6 for operands an operator does not accept, naming the
// operator and the operand types.
// Also: positions print as size_t (%zu).
static void operand_error(Ctx* ctx,
                          const AstNode* node,
                          AstDataType left,
                          AstDataType right) {
  if (ast_node_get_child_count(node) == 1)
    THROW(E_SEMANTIC_TYPE_ERROR,
          "operator '%s' at %zu:%zu cannot be applied to %s",
          operator_name(ast_node_get_type(node)), ast_node_get_line(node),
          ast_node_get_column(node), data_type_name(left));
  THROW(E_SEMANTIC_TYPE_ERROR,
        "operator '%s' at %zu:%zu cannot be applied to %s and %s",
        operator_name(ast_node_get_type(node)), ast_node_get_line(node),
        ast_node_get_column(node), data_type_name(left), data_type_name(right));
}

// Changes: new, the common type of two numeric operands; the Int side of a
// mixed pair is widened. Anything else is exit 6.
static AstDataType unify_numbers(Ctx* ctx,
                                 AstNode* node,
                                 AstDataType left,
                                 AstDataType right) {
  if (!is_number(left) || !is_number(right))
    operand_error(ctx, node, left, right);
  if (left == right)
    return left;
  size_t int_side =
      left == AST_DATA_TYPE_INT ? AST_BINARY_LEFT : AST_BINARY_RIGHT;
  widen_node(ctx, ast_node_child(ctx, node, int_side));
  return AST_DATA_TYPE_DOUBLE;
}

// Changes: new, a binary operator: + - * / on numbers, + on Strings, relations
// on numbers or Strings, == != on the same type or numbers, && || on Booleans;
// anything else is exit 6.
// Also: positions print as size_t (%zu).
static void check_binary(Ctx* ctx, Sema* sema, AstNode* node) {
  check_expr_children(ctx, sema, node, 0);
  AstNode* left = ast_node_child(ctx, node, AST_BINARY_LEFT);
  AstNode* right = ast_node_child(ctx, node, AST_BINARY_RIGHT);
  AstDataType lt = expr_type(ctx, left);
  AstDataType rt = expr_type(ctx, right);

  AstDataType result = AST_DATA_TYPE_UNKNOWN;
  switch (ast_node_get_type(node)) {
    case AST_NODE_ADD:
      if (lt == AST_DATA_TYPE_STRING && rt == AST_DATA_TYPE_STRING) {
        result = AST_DATA_TYPE_STRING;
        break;
      }
      result = unify_numbers(ctx, node, lt, rt);
      break;
    case AST_NODE_SUB:
    case AST_NODE_MUL:
    case AST_NODE_DIV:
      result = unify_numbers(ctx, node, lt, rt);
      break;
    case AST_NODE_LT:
    case AST_NODE_GT:
    case AST_NODE_LE:
    case AST_NODE_GE:
      if (!(lt == AST_DATA_TYPE_STRING && rt == AST_DATA_TYPE_STRING))
        (void)unify_numbers(ctx, node, lt, rt);
      result = AST_DATA_TYPE_BOOLEAN;
      break;
    case AST_NODE_EQ:
    case AST_NODE_NEQ:
      if (lt != rt)
        (void)unify_numbers(ctx, node, lt, rt);
      result = AST_DATA_TYPE_BOOLEAN;
      break;
    case AST_NODE_AND:
    case AST_NODE_OR:
      if (lt != AST_DATA_TYPE_BOOLEAN || rt != AST_DATA_TYPE_BOOLEAN)
        operand_error(ctx, node, lt, rt);
      result = AST_DATA_TYPE_BOOLEAN;
      break;
    default:
      THROW(E_INTERNAL_ERROR, "unexpected binary operator at %zu:%zu",
            ast_node_get_line(node), ast_node_get_column(node));
  }
  ast_node_set_data_type(node, result);
}

// Changes: new, a unary operator: NOT on Boolean, NEG on a number (keeps its
// type); anything else is exit 6.
static void check_unary(Ctx* ctx, Sema* sema, AstNode* node) {
  check_expr_children(ctx, sema, node, 0);
  AstNode* operand = ast_node_child(ctx, node, AST_UNARY_OPERAND);
  AstDataType type = expr_type(ctx, operand);
  if (ast_node_get_type(node) == AST_NODE_NOT) {
    if (type != AST_DATA_TYPE_BOOLEAN)
      operand_error(ctx, node, type, type);
  } else if (!is_number(type)) {
    operand_error(ctx, node, type, type);
  }
  ast_node_set_data_type(node, type);
}

// Changes: new, an interpolated string: every part is checked, any part type is
// accepted, the node is a String.
static void check_interp_string(Ctx* ctx, Sema* sema, AstNode* node) {
  check_expr_children(ctx, sema, node, 0);
  ast_node_set_data_type(node, AST_DATA_TYPE_STRING);
}

// Changes: new, the type of a call, read off the callee. An unchecked user
// function without a declared return type is checked on demand (pass state
// saved and restored); one already being checked is recursion, exit 6.
// Also: positions print as size_t (%zu).
static AstDataType call_result_type(Ctx* ctx,
                                    Sema* sema,
                                    const SymtableData* symbol) {
  AstNode* def = def_of_symbol(ctx, sema, symbol);
  if (def != NULL) {
    unsigned flags = ast_node_get_flags(def);
    if (!body_rule(ctx, def).declared) {
      if (flags & (unsigned)AST_FLAG_DEF_CHECKING) {
        AstNode* ident = ast_node_child(ctx, def, AST_DEF_IDENT);
        THROW(E_SEMANTIC_TYPE_ERROR,
              "function '%s' at %zu:%zu is used while its return type is being "
              "inferred, give it a declared return type",
              ast_node_get_name(ident), ast_node_get_line(ident),
              ast_node_get_column(ident));
      }
      if (!(flags & (unsigned)AST_FLAG_DEF_CHECKED)) {
        Sema saved = *sema;
        check_def(ctx, sema, def);
        *sema = saved;
      }
    }
  }
  return ir_to_data_type(ctx, symbol->ir_type);
}

// Changes: new, compares the checked arguments of a CALL with the callee
// signature: wrong count or type is exit 5, Int widens to Double. A built-in's
// Unit parameter (print, toStr) takes any argument.
// Also: positions print as size_t (%zu).
static void check_call_arguments(Ctx* ctx,
                                 const Sema* sema,
                                 AstNode* node,
                                 const SymtableData* symbol) {
  size_t argc = ast_node_get_child_count(node) - AST_CALL_FIRST_ARG;
  if (argc != symbol->param_count)
    THROW(E_SEMANTIC_ARGUMENT_ERROR,
          "call at %zu:%zu passes %zu argument(s) but the function takes %zu",
          ast_node_get_line(node), ast_node_get_column(node), argc,
          symbol->param_count);

  bool builtin = def_of_symbol(ctx, sema, symbol) == NULL;
  for (size_t i = 0; i < argc; i++) {
    IrType param = symbol->param_types[i];
    if (builtin && param == IR_UNIT)
      continue;
    require_compatible(ctx, ast_node_child(ctx, node, AST_CALL_FIRST_ARG + i),
                       ir_to_data_type(ctx, param), E_SEMANTIC_ARGUMENT_ERROR,
                       "an argument");
  }
}

// Changes: new, a CALL: callee resolved among functions (exit 3), BUILTIN flag
// for built-ins, arguments checked left to right and against the signature,
// type from call_result_type.
// Also: positions print as size_t (%zu).
static void check_call(Ctx* ctx, Sema* sema, AstNode* node) {
  AstNode* callee = ast_node_child(ctx, node, AST_CALL_CALLEE);
  if (ast_node_get_type(callee) != AST_NODE_IDENT)
    THROW(E_INTERNAL_ERROR, "callee at %zu:%zu is not a function name",
          ast_node_get_line(callee), ast_node_get_column(callee));

  SymtableData* symbol = resolve_function(ctx, callee);
  if (def_of_symbol(ctx, sema, symbol) == NULL)
    ast_node_set_flags(node,
                       ast_node_get_flags(node) | (unsigned)AST_FLAG_BUILTIN);
  check_expr_children(ctx, sema, node, AST_CALL_FIRST_ARG);
  check_call_arguments(ctx, sema, node, symbol);
  ast_node_set_data_type(node, call_result_type(ctx, sema, symbol));
}

// Changes: new, looks up the member entry "<receiver>.<member>" (ADR-0002) with
// the key on the C stack; a name too long for the buffer is simply not found.
static const SymtableData* resolve_member(Ctx* ctx,
                                          AstDataType receiver,
                                          const char* member) {
  char key[64];
  int length = snprintf(key, sizeof(key), "%s.%s", data_type_name(receiver),
                        member);
  if (length < 0 || (size_t)length >= sizeof(key))
    return NULL;
  return symtable_lookup(&ctx->global_symtable, key, false);
}

// Changes: new, whether the member exists on another receiver type, telling
// "abc".toInt (exit 6) from x.foo (exit 3).
static bool member_exists_elsewhere(Ctx* ctx,
                                    AstDataType receiver,
                                    const char* member) {
  for (size_t i = 0; i < TYPE_COUNT; i++)
    if (TYPES[i].data_type != receiver &&
        resolve_member(ctx, TYPES[i].data_type, member) != NULL)
      return true;
  return false;
}

// Changes: new, a MEMBER: resolved by its receiver's type, gets BUILTIN and the
// member's result type. A member of another receiver type is exit 6, an unknown
// name exit 3.
// Also: positions print as size_t (%zu).
static void check_member(Ctx* ctx, Sema* sema, AstNode* node) {
  check_expr_children(ctx, sema, node, 0);
  AstNode* receiver = ast_node_child(ctx, node, AST_MEMBER_RECEIVER);
  AstDataType receiver_type = expr_type(ctx, receiver);
  const char* member = ast_node_get_name(node);

  const SymtableData* symbol = resolve_member(ctx, receiver_type, member);
  if (symbol == NULL) {
    if (member_exists_elsewhere(ctx, receiver_type, member))
      THROW(E_SEMANTIC_TYPE_ERROR, "no member '%s' on %s at %zu:%zu", member,
            data_type_name(receiver_type), ast_node_get_line(node),
            ast_node_get_column(node));
    THROW(E_SEMANTIC_UNDEFINED_ERROR, "undefined member '%s' at %zu:%zu", member,
          ast_node_get_line(node), ast_node_get_column(node));
  }
  ast_node_set_symbol(node, symbol);
  ast_node_set_flags(node, ast_node_get_flags(node) |
                               (unsigned)AST_FLAG_BUILTIN);
  ast_node_set_data_type(node, ir_to_data_type(ctx, symbol->ir_type));
}

// Changes: new, expression dispatch, one case per node kind that can be an
// expression.
// Also: positions print as size_t (%zu).
static void check_expr(Ctx* ctx, Sema* sema, AstNode* node) {
  switch (ast_node_get_type(node)) {
    case AST_NODE_IDENT:
      check_ident(ctx, sema, node);
      break;
    case AST_NODE_INT_LIT:
    case AST_NODE_DOUBLE_LIT:
    case AST_NODE_STRING_LIT:
    case AST_NODE_BOOL_LIT:
    case AST_NODE_UNIT_LIT:
      check_literal(ctx, sema, node);
      break;
    case AST_NODE_ADD:
    case AST_NODE_SUB:
    case AST_NODE_MUL:
    case AST_NODE_DIV:
    case AST_NODE_EQ:
    case AST_NODE_NEQ:
    case AST_NODE_LT:
    case AST_NODE_GT:
    case AST_NODE_LE:
    case AST_NODE_GE:
    case AST_NODE_AND:
    case AST_NODE_OR:
      check_binary(ctx, sema, node);
      break;
    case AST_NODE_NOT:
    case AST_NODE_NEG:
      check_unary(ctx, sema, node);
      break;
    case AST_NODE_CALL:
      check_call(ctx, sema, node);
      break;
    case AST_NODE_MEMBER:
      check_member(ctx, sema, node);
      break;
    case AST_NODE_INTERP_STRING:
      check_interp_string(ctx, sema, node);
      break;
    case AST_NODE_IF:
      check_if(ctx, sema, node);
      break;
    case AST_NODE_RANGE_TO:
    case AST_NODE_RANGE_UNTIL:
      check_range(ctx, sema, node);
      break;
    default:
      THROW(E_INTERNAL_ERROR, "unexpected expression node at %zu:%zu",
            ast_node_get_line(node), ast_node_get_column(node));
  }
}

// Changes: new, statement dispatch; any other node is checked as an expression.
static void check_stmt(Ctx* ctx, Sema* sema, AstNode* node) {
  switch (ast_node_get_type(node)) {
    case AST_NODE_BLOCK:
      (void)check_block(ctx, sema, node, NULL);
      break;
    case AST_NODE_VAL:
    case AST_NODE_VAR:
      check_val_var(ctx, sema, node);
      break;
    case AST_NODE_ASSIGN:
      check_assign(ctx, sema, node);
      break;
    case AST_NODE_RETURN:
      check_return(ctx, sema, node);
      break;
    case AST_NODE_WHILE:
      check_while(ctx, sema, node);
      break;
    case AST_NODE_FOR:
      check_for(ctx, sema, node);
      break;
    default:
      check_expr(ctx, sema, node);
      break;
  }
}

// Changes: new, checks the DEF's body BLOCK in its parameter scope under
// body_rule; an omitted return type becomes the inferred type.
static void check_body(Ctx* ctx, Sema* sema) {
  AstNode* body = ast_node_child(ctx, sema->def, AST_DEF_BODY);
  ResultRule rule = body_rule(ctx, sema->def);
  AstDataType result = check_block(ctx, sema, body, &rule);
  if (rule.declared)
    return;

  AstNode* ident = ast_node_child(ctx, sema->def, AST_DEF_IDENT);
  SymtableData* symbol = symtable_lookup(
      &ctx->global_symtable, (char*)ast_node_get_name(ident), false);
  if (symbol == NULL)
    THROW(E_INTERNAL_ERROR, "function '%s' is not in the global scope",
          ast_node_get_name(ident));
  symbol->ir_type = data_type_to_ir(ctx, result);
}

// Changes: new, opens the parameter scope inside the global scope (also on
// demand), declares the read-only parameters (slots 0..n-1), checks the body
// while the DEF is marked as being checked; then a @main not returning Unit is
// exit 6.
// Also: positions print as size_t (%zu).
static void check_def(Ctx* ctx, Sema* sema, AstNode* def) {
  AstNode* params = NULL;
  size_t param_count = def_param_list(ctx, def, &params);

  Symtable* outer = sema->scope;
  ast_node_set_flags(def,
                     ast_node_get_flags(def) | (unsigned)AST_FLAG_DEF_CHECKING);
  sema->scope = ast_node_attach_scope(ctx, def, &ctx->global_symtable);
  for (size_t i = 0; i < param_count; i++) {
    AstNode* param = ast_node_child(ctx, params, i);
    AstNode* ident = ast_node_child(ctx, param, AST_PARAM_IDENT);
    AstNode* type = ast_node_child(ctx, param, AST_PARAM_TYPE);
    declare_variable(ctx, sema, ident, annotation_to_ir(ctx, type), true, i);
  }

  sema->def = def;
  sema->next_slot = param_count;
  check_body(ctx, sema);
  sema->def = NULL;
  sema->scope = outer;

  ast_node_set_flags(
      def, (ast_node_get_flags(def) & ~(unsigned)AST_FLAG_DEF_CHECKING) |
               (unsigned)AST_FLAG_DEF_CHECKED);
  AstNode* ident = ast_node_child(ctx, def, AST_DEF_IDENT);
  if ((ast_node_get_flags(def) & (unsigned)AST_FLAG_MAIN) &&
      ast_node_get_symbol(ident)->ir_type != IR_UNIT)
    THROW(E_SEMANTIC_TYPE_ERROR,
          "@main function '%s' at %zu:%zu must return Unit",
          ast_node_get_name(ident), ast_node_get_line(ident),
          ast_node_get_column(ident));
}

// Changes: new, phase 2: checks every function in source order, skipping those
// already checked on demand.
static void check_functions(Ctx* ctx, Sema* sema) {
  size_t count = ast_node_get_child_count(sema->program);
  for (size_t i = 0; i < count; i++) {
    AstNode* def = ast_node_child(ctx, sema->program, i);
    if (ast_node_get_flags(def) & (unsigned)AST_FLAG_DEF_CHECKED)
      continue;
    check_def(ctx, sema, def);
  }
}

// Changes: new, whether any user call under node reaches target, directly or
// indirectly; each DEF is walked once per search, unreachable calls count too
// (PDF 2.3).
// NOLINTNEXTLINE(misc-no-recursion)
static bool calls_reach(Ctx* ctx,
                        const Sema* sema,
                        AstNode* node,
                        const AstNode* target) {
  if (ast_node_get_type(node) == AST_NODE_CALL) {
    AstNode* callee = ast_node_child(ctx, node, AST_CALL_CALLEE);
    AstNode* def = def_of_symbol(ctx, sema, ast_node_get_symbol(callee));
    if (def == target)
      return true;
    if (def != NULL &&
        !(ast_node_get_flags(def) & (unsigned)AST_FLAG_DEF_CHECKING)) {
      ast_node_set_flags(
          def, ast_node_get_flags(def) | (unsigned)AST_FLAG_DEF_CHECKING);
      AstNode* body = ast_node_child(ctx, def, AST_DEF_BODY);
      if (calls_reach(ctx, sema, body, target))
        return true;
    }
  }
  size_t count = ast_node_get_child_count(node);
  for (size_t i = 0; i < count; i++) {
    AstNode* child = ast_node_child(ctx, node, i);
    if (calls_reach(ctx, sema, child, target))
      return true;
  }
  return false;
}

// Changes: new, phase 3: a function in direct or indirect recursion must
// declare its return type (PDF 2.3), exit 6.
// Also: positions print as size_t (%zu).
static void check_recursion(Ctx* ctx, const Sema* sema) {
  size_t count = ast_node_get_child_count(sema->program);
  for (size_t i = 0; i < count; i++) {
    AstNode* def = ast_node_child(ctx, sema->program, i);
    if (body_rule(ctx, def).declared)
      continue;
    AstNode* body = ast_node_child(ctx, def, AST_DEF_BODY);
    bool recursive = calls_reach(ctx, sema, body, def);
    for (size_t j = 0; j < count; j++) {
      AstNode* other = ast_node_child(ctx, sema->program, j);
      ast_node_set_flags(
          other, ast_node_get_flags(other) & ~(unsigned)AST_FLAG_DEF_CHECKING);
    }
    if (recursive) {
      AstNode* ident = ast_node_child(ctx, def, AST_DEF_IDENT);
      THROW(E_SEMANTIC_TYPE_ERROR,
            "recursive function '%s' at %zu:%zu needs a declared return type",
            ast_node_get_name(ident), ast_node_get_line(ident),
            ast_node_get_column(ident));
    }
  }
}

// Changes: new, the public entry point, runs the phases over ctx->ast with the
// context's global symtable as the global scope.
void semantics_analyze(Ctx* ctx) {
  if (ctx->ast == NULL || ast_node_get_type(ctx->ast) != AST_NODE_PROGRAM)
    THROW(E_INTERNAL_ERROR, "semantic analysis needs a PROGRAM in ctx->ast");

  Sema sema = {
      .program = ctx->ast,
      .scope = &ctx->global_symtable,
      .def = NULL,
      .next_slot = 0,
  };
  insert_members(ctx, &sema);
  collect_functions(ctx, &sema);
  check_functions(ctx, &sema);
  check_recursion(ctx, &sema);
}
